//go:build s390x

package floats

// Add32, Sub32, Mul32, Div32 and Sqrt32 VXE kernels (binop32.go), generated by
// go-asmgen (binop32_s390x_gen.go) into binop32_s390x.s, gated on hasVXE
// (extrema32_s390x.go): the single-precision vector operations come with the
// vector-enhancements facility 1 of a z14 or later. One IEEE binary32 operation
// per element, no fused instruction: bit-identical to the portable loops. The
// callers pass every slice already sliced to the common length; an empty one
// never reaches a kernel.
//
//go:noescape
func add32VXE(dst, a, b *float32, n int)

//go:noescape
func sub32VXE(dst, a, b *float32, n int)

//go:noescape
func mul32VXE(dst, a, b *float32, n int)

//go:noescape
func div32VXE(dst, a, b *float32, n int)

//go:noescape
func sqrt32VXE(dst, src *float32, n int)

func add32(dst, a, b []float32) {
	if len(a) == 0 || !hasVXE {
		add32Ref(dst, a, b)
		return
	}
	add32VXE(&dst[0], &a[0], &b[0], len(a))
}

func sub32(dst, a, b []float32) {
	if len(a) == 0 || !hasVXE {
		sub32Ref(dst, a, b)
		return
	}
	sub32VXE(&dst[0], &a[0], &b[0], len(a))
}

func mul32(dst, a, b []float32) {
	if len(a) == 0 || !hasVXE {
		mul32Ref(dst, a, b)
		return
	}
	mul32VXE(&dst[0], &a[0], &b[0], len(a))
}

func div32(dst, a, b []float32) {
	if len(a) == 0 || !hasVXE {
		div32Ref(dst, a, b)
		return
	}
	div32VXE(&dst[0], &a[0], &b[0], len(a))
}

func sqrt32(dst, src []float32) {
	if len(src) == 0 || !hasVXE {
		sqrt32Ref(dst, src)
		return
	}
	sqrt32VXE(&dst[0], &src[0], len(src))
}
